mapper.select:
SELECT user_id, module_name, api_path, use_count, last_access_time
FROM sys_api_usage_stat
WHERE user_id = #{userId}
ORDER BY use_count DESC, last_access_time DESC
LIMIT #{limit}

SELECT COUNT(DISTINCT module_name) FROM sys_api_usage_stat
AND user_id = #{userId}
AND module_name LIKE CONCAT('%', #{moduleName}, '%')

SELECT module_name, MAX(api_path) AS api_path, SUM(use_count) AS total_use_count, COUNT(DISTINCT user_id) AS user_count, MAX(last_access_time) AS last_access_time FROM sys_api_usage_stat
AND user_id = #{userId}
AND module_name LIKE CONCAT('%', #{moduleName}, '%')
GROUP BY module_name ORDER BY SUM(use_count) DESC, MAX(last_access_time) DESC LIMIT #{limit} OFFSET #{offset}

SELECT stat.user_id::text AS user_id, usr.username, usr.nickname, stat.use_count, stat.last_access_time FROM sys_api_usage_stat stat LEFT JOIN sys_user usr ON usr.id = stat.user_id WHERE stat.module_name = #{moduleName}
AND (usr.username LIKE CONCAT('%', #{keyword}, '%') OR usr.nickname LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY stat.use_count DESC, stat.last_access_time DESC LIMIT #{limit} OFFSET #{offset}
